export const script = "\n    function switchThumbnail(index) {\n      const thumbs = document.querySelectorAll('.thumb-btn');\n      thumbs.forEach((btn, i) => {\n        if (i === index) {\n          btn.classList.add('ring-2', 'ring-primary', 'opacity-100');\n          btn.classList.remove('opacity-70');\n        } else {\n          btn.classList.remove('ring-2', 'ring-primary', 'opacity-100');\n          btn.classList.add('opacity-70');\n        }\n      });\n    }\n\n    function switchTab(tabId) {\n      const tabs = ['overview', 'included', 'specs', 'reviews', 'faq'];\n      tabs.forEach(t => {\n        const panel = document.getElementById('tab-content-' + t);\n        const btn = document.getElementById('tab-btn-' + t);\n        if (t === tabId) {\n          if (panel) panel.classList.remove('hidden');\n          if (btn) {\n            btn.classList.add('bg-surface', 'text-on-surface', 'shadow-sm');\n            btn.classList.remove('text-text-muted');\n          }\n        } else {\n          if (panel) panel.classList.add('hidden');\n          if (btn) {\n            btn.classList.remove('bg-surface', 'text-on-surface', 'shadow-sm');\n            btn.classList.add('text-text-muted');\n          }\n        }\n      });\n    }\n\n    function selectLicense(type, price) {\n      const displayPrice = document.getElementById('display-price');\n      if (displayPrice) {\n        displayPrice.textContent = price;\n      }\n      \n      const cards = document.querySelectorAll('.license-card');\n      cards.forEach(card => {\n        card.classList.remove('bg-primary-fixed/30', 'shadow-sm');\n        card.classList.add('bg-surface-container-low');\n      });\n\n      const selectedInput = document.querySelector('input[value=\"' + type + '\"]');\n      if (selectedInput) {\n        selectedInput.checked = true;\n        const parentCard = selectedInput.closest('.license-card');\n        if (parentCard) {\n          parentCard.classList.remove('bg-surface-container-low');\n          parentCard.classList.add('bg-primary-fixed/30', 'shadow-sm');\n        }\n      }\n    }\n  ";
export const bodyClass = "bg-background font-body-md text-on-surface antialiased";
export const scope = "mk-product";
